const ensureUniqueContractNumber = async (contractNumber: string | undefined, excludeId?: number) => { const displayNumber = contractNumber?.trim() ?? ""; const normalized = displayNumber.toLocaleLowerCase(); if (!normalized) return; const duplicate = (await listContracts()).find(item => item.id !== excludeId && item.contractNumber?.trim().toLocaleLowerCase() === normalized); if (duplicate) throw new Error(`Договор с номером «${displayNumber}» уже существует`); }; const recalculateDraftAccrualsForContract = async (contract: any) => { const rows = (await listAccruals()).filter(row => row.contractId === contract.id && row.status === "draft" && !row.amountEdited); for (const row of rows) { const result = calculateAccrual({ startDate: toDateOnly(contract.startDate), endDate: toDateOnly(contract.endDate), terminationDate: contract.terminationDate ? toDateOnly(contract.terminationDate) : null, tariffType: contract.tariffType, tariffAmount: Number(contract.tariffAmount) }, row.period); if (!result) { await deleteAccrual(row.id); continue; } await updateAccrual(row.id, { serviceFrom: new Date(result.serviceFrom + "T00:00:00Z"), serviceTo: new Date(result.serviceTo + "T00:00:00Z"), quantity: result.quantity.toFixed(2), amount: result.amount.toFixed(2), tenantName: contract.tenantName, tenantEmail: contract.tenantEmail ?? null, tenantCategory: contract.tenantCategory ?? null, tenantNumber: contract.tenantNumber ?? null, propertyName: contract.propertyName, unitName: contract.unitName ?? null, tariffType: contract.tariffType, tariffAmount: String(contract.tariffAmount) }); } return rows.length; };
